(function(E){ const x = E["int-m2"] = E["int-m2"] || {units:{}}; x.units["int-11"] = {"grammar":{"id":"c-int-11-g","level":"B1","course":"interview","unit":"int-11","title":"Suggestions in a group: could, Why don't we, How about + -ing","titleTr":"Grupta öneri: could, Why don't we, How about + -ing","titleFa":"پیشنهاد دادن در گروه: could، Why don't we و How about + ‎-ing","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Soft suggestion: could + verb","We could start with the budget."],["Ask the group: Why don't we + verb?","Why don't we hear from everyone first?"],["How about + -ing?","How about testing it in one shop?"],["Build first: Building on ...","Building on Jon's idea, we could ask the client."]]},"wrong":"Why we don't vote on the three ideas?","right":"Why don't we vote on the three ideas?","blank":{"sentence":"How about ___ the client what they need first?","word":"asking","distractors":["ask","to ask"]},"wrong2":"How about start with the cheapest option?","right2":"How about starting with the cheapest option?","blank2":{"sentence":"Why ___ each person two minutes to speak?","word":"don't we give","distractors":["we don't give","don't we giving"],"hint2":{"en":"It is a question, so the helper verb comes before we. And after Why don't we, which form of the verb?","tr":"Bu bir soru, bu yüzden yardımcı fiil we'den önce gelir. Peki Why don't we'den sonra fiil hangi biçimde olur?","fa":"این یک سؤال است، پس فعل کمکی قبل از ⁨we⁩ می‌آید. بعد از ⁨Why don't we⁩ فعل به چه شکلی می‌آید؟"},"why":{"en":"don't we give: in a question, don't comes before we, and the verb after it stays plain. 'We don't give' keeps statement order, and the -ing form goes with How about.","tr":"don't we give: soruda don't, we'den önce gelir ve ardından gelen fiil yalın kalır. 'We don't give' düz cümle sırasını korur; -ing biçimi ise How about ile kullanılır.","fa":"⁨don't we give⁩: در سؤال، ⁨don't⁩ قبل از ⁨we⁩ می‌آید و فعل بعدش ساده می‌ماند. ⁨we don't give⁩ ترتیب جمله‌ی خبری را نگه می‌دارد و شکل ⁨ing⁩ با ⁨How about⁩ می‌آید."}},"expParts":{"rule":[{"en":"Use could + verb for a soft idea, because it leaves room for others.","tr":"Yumuşak bir fikir için could + fiil kullan, çünkü başkalarına da yer bırakır.","fa":"برای پیشنهاد نرم could و فعل ساده بیاور، چون برای نظر دیگران هم جا می‌گذارد.","ex":"We could start with the budget."},{"en":"Ask with Why don't we + verb? to invite the whole group.","tr":"Bütün grubu davet etmek için Why don't we + fiil? diye sor.","fa":"برای اینکه همه‌ی گروه را به بحث دعوت کنی، با Why don't we و فعل ساده بپرس.","ex":"Why don't we hear from everyone first?"},{"en":"After How about, use -ing, because about is a preposition.","tr":"How about'tan sonra -ing kullan, çünkü about bir edattır.","fa":"بعد از How about فعل ing‌دار بیاور، چون about حرف اضافه است و بعد از حرف اضافه فعل ing می‌گیرد.","ex":"How about testing it in one shop?"}],"test":{"en":"After How about, add -ing. After could and Why don't we, use the plain verb.","tr":"How about'tan sonra -ing ekle. could ve Why don't we'den sonra yalın fiil kullan.","fa":"بعد از How about فعل ing‌دار بیاور و بعد از could و Why don't we فعل ساده."},"contrast":{"en":"Turkish and Persian keep statement order in questions, so learners say 'Why we don't vote?'. English puts don't before we.","tr":"Türkçede soru da düz cümle sırasıyla kurulur; bu yüzden 'Why we don't vote?' denir. İngilizcede don't, we'den önce gelir: Why don't we vote?","fa":"در فارسی جمله‌ی پرسشی همان ترتیب جمله‌ی خبری را دارد؛ برای همین می‌گوییم «Why we don't vote?». در انگلیسی don't قبل از we می‌آید: Why don't we vote?"}},"errorWatch":[{"find":["why we don't","why we not","how about start","how about ask","how about use","how about make","how about take","how about try","how about to"],"fix":{"en":"Say 'Why don't we...?', and use -ing after How about: 'How about starting with the budget?'","tr":"'Why don't we...?' de ve How about'tan sonra -ing kullan: 'How about starting with the budget?'","fa":"بگو «Why don't we...?» و بعد از How about فعل ing‌دار بیاور: «How about starting with the budget?»"}},{"find":["we could to","could we to"],"fix":{"en":"After could, use the plain verb: 'We could ask the client.'","tr":"could'dan sonra yalın fiil kullan: 'We could ask the client.'","fa":"بعد از could فعل ساده بیاور: «We could ask the client.»"}}]},"b2":{"id":"c-int-11-b2","level":"B2","track":"B2","course":"interview","unit":"int-11","title":"Disagree softly and sum up","titleTr":"Kibarca karşı çık ve özetle","titleFa":"مخالفت نرم و جمع‌بندی","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Wouldn't it be better to + verb?","Wouldn't it be better to test it first?"],["I see your point, but + reason","I see your point, but the budget is small."],["So, to sum up, + what you agreed","So, to sum up, we start in one café."]]},"wrong":"Wouldn't it be better test it first?","right":"Wouldn't it be better to test it first?","blank":{"sentence":"Wouldn't it be better ___ for the client's answer?","word":"to wait","distractors":["waiting","wait"]},"wrong2":"So, to sum, we start in one café.","right2":"So, to sum up, we start in one café.","blank2":{"sentence":"So, ___ up, we agree on two ideas and one test.","word":"to sum","distractors":["for sum","to summary"]},"useIn":{"en":"B2: in your speaking, disagree once with 'I see your point, but...' and close with 'So, to sum up, ...'.","tr":"B2: konuşmanda bir kez 'I see your point, but...' ile karşı çık ve 'So, to sum up, ...' ile kapat.","fa":"در مسیر B2: در صحبتت یک بار با «I see your point, but...» مخالفت کن و با «So, to sum up, ...» جمع‌بندی کن."},"exitItem":{"from":"int-11","kind":"blank","prompt":"I see your point, ___ the deadline is only two weeks away.","options":["but","so","because of"],"correct":0,"why":{"en":"but: 'I see your point, but...' accepts the idea, then gives a different view. 'So' shows a result, and 'because of' needs a noun.","tr":"but: 'I see your point, but...' fikri kabul eder, sonra farklı bir görüş verir. 'So' sonuç bildirir; 'because of' isim ister.","fa":"but درست است، چون I see your point, but اول ایده را می‌پذیرد و بعد نظر دیگری می‌دهد. so نتیجه را نشان می‌دهد و because of اسم می‌خواهد."},"hint2":{"en":"You accept their point first, then you disagree. Which word turns the sentence the other way?","tr":"Önce onların görüşünü kabul ediyorsun, sonra katılmadığını söylüyorsun. Cümleyi ters yöne çeviren kelime hangisi?","fa":"اول حرفشان را قبول می‌کنی و بعد مخالفتت را می‌گویی. کدام کلمه جمله را به سمت مخالف می‌برد؟"}},"expParts":{"rule":[{"en":"Disagree with a question: Wouldn't it be better to + verb?","tr":"Soruyla karşı çık: Wouldn't it be better to + fiil?","fa":"مخالفتت را با سؤال بگو: Wouldn't it be better to و فعل.","ex":"Wouldn't it be better to test it first?"},{"en":"Accept the point, then give your reason with but.","tr":"Önce görüşü kabul et, sonra but ile nedenini söyle.","fa":"اول حرف طرف را بپذیر و بعد با but دلیلت را بگو.","ex":"I see your point, but the budget is small."},{"en":"Close the task: So, to sum up, + what you agreed.","tr":"Görevi kapat: So, to sum up, + üzerinde anlaştığınız şey.","fa":"کار را جمع کن: So, to sum up و بعد چیزی که رویش توافق کردید.","ex":"So, to sum up, we start in one café."}],"test":{"en":"Disagreeing? Accept first, then but. Closing? So, to sum up.","tr":"Karşı mı çıkıyorsun? Önce kabul et, sonra but. Kapatıyor musun? So, to sum up.","fa":"مخالفی؟ اول بپذیر و بعد but. جمع‌بندی می‌کنی؟ So, to sum up."},"contrast":{"en":"Turkish 'Ama...' and Persian 'ولی...' often open a direct no. In an English group task, accept the point first; it sounds like teamwork.","tr":"Türkçede 'Ama...' çoğu zaman doğrudan bir hayırla başlar. İngilizce bir grup görevinde önce görüşü kabul et; bu takım çalışması gibi duyulur.","fa":"در فارسی «ولی...» اغلب یعنی یک «نه»ی مستقیم. در کار گروهی به انگلیسی اول حرف طرف را بپذیر؛ این‌طوری حرفت شبیه کار تیمی است."}},"errorWatch":[{"find":["better test","better try","better ask","better wait","to sum,","to summary","for sum up"],"fix":{"en":"Say 'Wouldn't it be better to + verb?' and 'So, to sum up, ...'.","tr":"'Wouldn't it be better to + fiil?' ve 'So, to sum up, ...' de.","fa":"بگو «Wouldn't it be better to + فعل؟» و «So, to sum up, ...»."}}]},"vocab":{"id":"c-int-11-v","level":"B1","category":"vocab","course":"interview","unit":"int-11","goals":["career"],"title":{"en":"Panels, Group Tasks and Tests","tr":"Heyetler, Grup Görevleri ve Testler","fa":"هیئت مصاحبه، کار گروهی و آزمون"},"cards":[{"word":"panel","sentence":"There were three people on the panel.","meaning":{"en":"A group of people who interview you together.","tr":"mülakat heyeti; seninle birlikte görüşen kişiler.","fa":"هیئت مصاحبه؛ چند نفر که با هم از تو مصاحبه می‌کنند."}},{"word":"assessment centre","sentence":"The assessment centre lasts a full day.","meaning":{"en":"A day of tasks, tests and interviews for several candidates.","tr":"değerlendirme merkezi; birkaç aday için görev, test ve mülakatlardan oluşan gün.","fa":"مرکز ارزیابی؛ یک روز کامل کار، آزمون و مصاحبه برای چند داوطلب."}},{"word":"group exercise","sentence":"In the group exercise, five candidates plan an event together.","meaning":{"en":"A task you do with other candidates while assessors watch.","tr":"grup çalışması; değerlendiriciler izlerken diğer adaylarla yaptığın görev.","fa":"تمرین گروهی؛ کاری که با داوطلب‌های دیگر انجام می‌دهی و ارزیاب‌ها تماشا می‌کنند."}},{"word":"assessor","sentence":"The assessors take notes the whole time.","meaning":{"en":"A person who watches and scores candidates.","tr":"değerlendirici.","fa":"ارزیاب."},"gap":"assessors","accept":["assessors"]},{"word":"brief","sentence":"Read the brief twice before you start.","meaning":{"en":"Here: the written instructions for a task.","tr":"burada: bir görevin yazılı talimatları.","fa":"اینجا: دستورالعمل نوشته‌شده‌ی یک کار."}},{"word":"case study","sentence":"The case study gives you a real business problem to solve.","meaning":{"en":"A task where you solve a real or realistic problem.","tr":"vaka çalışması.","fa":"مطالعه‌ی موردی؛ کاری که در آن یک مسئله‌ی واقعی را حل می‌کنی."}},{"word":"aptitude test","sentence":"The aptitude test has 20 number questions in 20 minutes.","meaning":{"en":"A timed test of skills such as numbers or logic.","tr":"yetenek testi; sayı ya da mantık gibi beceriler için süreli test.","fa":"آزمون استعداد؛ آزمون زمان‌دار مهارت‌هایی مثل عدد یا منطق."}},{"word":"build on","sentence":"Building on Jon's idea, we could ask the client.","meaning":{"en":"To add to someone else's idea.","tr":"birinin fikrinin üzerine bir şey eklemek.","fa":"ایده‌ی کسی را ادامه دادن و کامل کردن."},"gap":"Building on","accept":["building on"]},{"word":"sum up","sentence":"Let me sum up what we agreed.","meaning":{"en":"To say the main points again, briefly.","tr":"özetlemek.","fa":"جمع‌بندی کردن."}},{"word":"clarify","sentence":"Can I clarify one thing before we start?","meaning":{"en":"To make something clear by asking or explaining.","tr":"netleştirmek; açıklığa kavuşturmak.","fa":"روشن کردن؛ با پرسیدن یا توضیح دادن."}}]},"judge":{"id":"c-int-11-j","course":"interview","unit":"int-11","type":"judge","title":{"en":"In the group task","tr":"Grup görevinde","fa":"در کار گروهی"},"prompt":"Five things candidates said in a 20-minute group task: choose one new product for a chain of cafés.","parts":["Builds on others","Moves the task forward","Brings others in"],"instruction":{"en":"Tap what each line does. The strongest line does all three.","tr":"Her cümlenin ne yaptığına dokun. En güçlü cümle üçünü de yapar.","fa":"روی کاری که هر جمله می‌کند بزن. قوی‌ترین جمله هر سه را انجام می‌دهد."},"items":[{"by":"Graduate","answer":"No, that's a bad idea. Mine is much better, so let's just do mine.","present":[],"fix":{"en":"This shuts the others down, and assessors note how you treat people. Build first: 'I like the price in Jon's idea. We could add...'","tr":"Bu diğerlerini susturur ve değerlendiriciler insanlara nasıl davrandığını not eder. Önce üzerine ekle: 'I like the price in Jon's idea. We could add...'","fa":"این حرف بقیه را ساکت می‌کند و ارزیاب‌ها رفتارت با دیگران را یادداشت می‌کنند. اول حرف آن‌ها را ادامه بده: «I like the price in Jon's idea. We could add...»"}},{"by":"Engineer","answer":"I agree with everything.","present":[],"fix":{"en":"Silence is noted too, and 'I agree' adds nothing. Give one idea in the first five minutes: 'We could start by listing the costs.'","tr":"Sessizlik de not edilir ve 'I agree' hiçbir şey eklemez. İlk beş dakikada bir fikir söyle: 'We could start by listing the costs.'","fa":"سکوت هم یادداشت می‌شود و «I agree» چیزی اضافه نمی‌کند. در پنج دقیقه‌ی اول یک ایده بگو: «We could start by listing the costs.»"}},{"by":"Nurse","answer":"Building on Jon's idea, we could test the new drink in one café first.","present":["Builds on others","Moves the task forward"],"fix":{"en":"Good. Now bring someone in by name: '...Sara, would that work with the budget?'","tr":"İyi. Şimdi birini adıyla dahil et: '...Sara, would that work with the budget?'","fa":"خوب است. حالا یک نفر را با اسمش وارد بحث کن: «...Sara, would that work with the budget?»"}},{"by":"Sales assistant","answer":"We have ten minutes left, so I will decide: we do the cold drinks.","present":["Moves the task forward"],"fix":{"en":"Good timekeeping, but you decide alone. Ask the group: 'We have ten minutes left. Why don't we vote on the top two ideas?'","tr":"Zamanı iyi takip ediyorsun ama tek başına karar veriyorsun. Gruba sor: 'We have ten minutes left. Why don't we vote on the top two ideas?'","fa":"حواست به وقت هست، ولی تنهایی تصمیم می‌گیری. از گروه بپرس: «We have ten minutes left. Why don't we vote on the top two ideas?»"}},{"by":"Good model","answer":"Building on Jon's point, how about testing it in one café first? Sara, you haven't said much yet. What do you think?","present":["Builds on others","Moves the task forward","Brings others in"],"fix":null}]},"speaking":{"id":"int-11","course":"interview","unit":"int-11","topic":{"en":"A panel, a group task and a missed question","tr":"Bir heyet, bir grup görevi ve kaçırılan bir soru","fa":"هیئت مصاحبه، کار گروهی و سؤالی که نشنیدی"},"warmup":{"en":"Put three objects on the table as the panel: a cup, a book, a phone. Look at each one and say good morning.","tr":"Masaya heyet olarak üç eşya koy: bir fincan, bir kitap, bir telefon. Her birine bak ve günaydın de.","fa":"سه وسیله را به‌جای هیئت مصاحبه روی میز بگذار: یک لیوان، یک کتاب و یک گوشی. به هر کدام نگاه کن و صبح‌به‌خیر بگو."},"questions":[{"en":"A panel of three: Ms Ersoy (HR), Mr Rostami (your future manager) and Ms Lopez (a team member). Greet them, using each name once.","tr":"Üç kişilik bir heyet: Ms Ersoy (İK), Mr Rostami (gelecekteki yöneticin) ve Ms Lopez (bir ekip üyesi). Her ismi bir kez kullanarak onları selamla.","fa":"هیئتی سه‌نفره: Ms Ersoy (منابع انسانی)، Mr Rostami (مدیر آینده‌ات) و Ms Lopez (یکی از اعضای تیم). با هر کدام یک بار با اسمش سلام کن."},{"en":"Mr Rostami asks: \"Tell me about a time you worked in a team.\" Answer him first, then look at the others too.","tr":"Mr Rostami soruyor: \"Tell me about a time you worked in a team.\" Önce ona cevap ver, sonra diğerlerine de bak.","fa":"Mr Rostami می‌پرسد: «Tell me about a time you worked in a team.» اول به خودش جواب بده و بعد به بقیه هم نگاه کن."},{"en":"Ms Lopez asks a long, fast question and you miss the end. Say which part you missed and ask again.","tr":"Ms Lopez uzun ve hızlı bir soru soruyor, sonunu kaçırıyorsun. Hangi kısmı kaçırdığını söyle ve yeniden sor.","fa":"Ms Lopez یک سؤال طولانی و تند می‌پرسد و آخرش را نمی‌شنوی. بگو کدام قسمت را نشنیدی و دوباره بپرس."},{"en":"Group task: \"Choose one new product for a café chain.\" Give your idea in one sentence, then build on Jon's idea: a cold drink.","tr":"Grup görevi: \"Choose one new product for a café chain.\" Fikrini tek cümleyle söyle, sonra Jon'un soğuk içecek fikrinin üzerine ekle.","fa":"کار گروهی: «Choose one new product for a café chain.» ایده‌ات را در یک جمله بگو و بعد ایده‌ی Jon را، یعنی یک نوشیدنی سرد، ادامه بده."},{"en":"Case task: you get a written brief and 20 minutes. Check one thing before you start, then say how you will use the time.","tr":"Vaka görevi: yazılı bir talimat ve 20 dakika alıyorsun. Başlamadan önce bir şeyi netleştir, sonra süreyi nasıl kullanacağını söyle.","fa":"کار موردی: یک دستورالعمل نوشته‌شده و ۲۰ دقیقه وقت داری. قبل از شروع یک چیز را روشن کن و بعد بگو وقتت را چطور تقسیم می‌کنی."}],"followups":[{"en":"Do it again in 60 seconds, then 45. Use one name in each round.","tr":"Önce 60, sonra 45 saniyede yeniden yap. Her turda bir isim kullan.","fa":"دوباره در ۶۰ و بعد ۴۵ ثانیه انجامش بده. در هر دور یک اسم را به کار ببر."}],"expressions":[{"phrase":"That's a good question, Ms Lopez.","meaning":{"en":"Uses the name of the person who asked.","tr":"Soruyu soranın adını kullanır.","fa":"اسم کسی را که پرسیده به کار می‌برد."}},{"phrase":"Sorry, I missed the last part.","meaning":{"en":"Says exactly what you didn't catch.","tr":"Tam olarak neyi kaçırdığını söyler.","fa":"دقیقاً می‌گوید کدام قسمت را نشنیدی."}},{"phrase":"Building on Jon's idea, ...","meaning":{"en":"Adds to someone else's idea before yours.","tr":"Kendi fikrinden önce başkasının fikrine ekler.","fa":"پیش از ایده‌ی خودت، ایده‌ی کس دیگری را ادامه می‌دهد."}}],"selfCheck":[{"en":"I used each panel member's name once.","tr":"Heyetteki herkesin adını bir kez kullandım.","fa":"اسم هر کدام از اعضای هیئت را یک بار به کار بردم."},{"en":"I answered the person who asked, then looked at the others.","tr":"Soruyu sorana cevap verdim, sonra diğerlerine de baktım.","fa":"به کسی که پرسید جواب دادم و بعد به بقیه هم نگاه کردم."},{"en":"I said which part I missed, not just \"Sorry?\".","tr":"Sadece \"Sorry?\" demedim, hangi kısmı kaçırdığımı söyledim.","fa":"فقط نگفتم «Sorry?»؛ گفتم کدام قسمت را نشنیدم."},{"en":"I built on someone else's idea before giving mine.","tr":"Kendi fikrimi söylemeden önce başkasının fikrine ekledim.","fa":"پیش از گفتن ایده‌ی خودم، ایده‌ی کس دیگری را ادامه دادم."}],"model":"Good morning, Ms Ersoy, Mr Rostami, Ms Lopez. Thank you for having me. That's a good question, Mr Rostami. Last year our team moved 300 customers to a new system in two weeks. I planned the calls, and we finished two days early. Sorry, Ms Lopez, I missed the last part. Could you say it again? Building on Jon's idea, how about testing the cold drink in one café first?"},"writing":{"id":"c-int-11-w","course":"interview","unit":"int-11","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"model":"Recommendation: we could sell a cold brew coffee in one café for one month.\nProblem: summer sales fall by about 20%.\nWhy: cold drinks sold 30% more this year than last year, and cold brew is easy to make in large amounts.\nRisk: it may not sell on cool days, so we test it in one café first.\nNext step: if it sells 40 cups a day, I recommend adding it to all 12 cafés in June.","frame":"Recommendation: we could ___.\nProblem: ___.\nWhy: ___.\nRisk: ___, so ___.\nNext step: if ___, I recommend ___.","words":[{"word":"could"},{"word":"recommend"}],"minWords":60,"minSentences":4,"title":{"en":"Your case-task recommendation","tr":"Vaka görevi önerin","fa":"پیشنهاد تو در کار موردی"},"prompt":{"en":"Case task, 20 minutes. A chain of 12 cafés sells about 20% less in summer; cold drinks sold 30% more this year. Write a short recommendation (60-90 words): the problem, your idea, one reason with a number, one risk, and the next step. Use 'we could' or 'I recommend' once.","tr":"Vaka görevi, 20 dakika. 12 kafelik bir zincir yazın yaklaşık %20 daha az satıyor; soğuk içecekler bu yıl %30 daha çok sattı. Kısa bir öneri yaz (60-90 kelime): sorun, fikrin, sayı içeren bir neden, bir risk ve sonraki adım. 'we could' ya da 'I recommend' ifadesini bir kez kullan.","fa":"کار موردی، ۲۰ دقیقه. یک زنجیره‌ی ۱۲ کافه‌ای در تابستان حدود ۲۰ درصد کمتر می‌فروشد؛ نوشیدنی‌های سرد امسال ۳۰ درصد بیشتر فروش داشتند. یک پیشنهاد کوتاه بنویس (۶۰ تا ۹۰ کلمه): مشکل، ایده‌ات، یک دلیل با عدد، یک ریسک و قدم بعدی. یک بار از «we could» یا «I recommend» استفاده کن."},"rubric":["Task done: the problem, one idea, a reason with a number, a risk, the next step","Organised: one short line for each part, in that order","Language: could or I recommend + -ing for the idea; if for the next step","Tone: clear and decided: one idea, not five"],"rubricI18n":{"tr":["Görev: sorun, bir fikir, sayı içeren bir neden, bir risk, sonraki adım","Düzen: her parça için kısa bir satır, bu sırayla","Dil: fikir için could ya da I recommend + -ing; sonraki adım için if","Üslup: net ve kararlı: beş değil, tek fikir"],"fa":["کامل بودن کار: مشکل، یک ایده، یک دلیل با عدد، یک ریسک، قدم بعدی","نظم: برای هر بخش یک خط کوتاه، به همین ترتیب","زبان: could یا I recommend + ‎-ing برای ایده؛ if برای قدم بعدی","لحن: روشن و قاطع؛ یک ایده، نه پنج تا"]},"parts":[{"t":{"en":"The problem","tr":"Sorun","fa":"مشکل"},"find":["problem","fall by","falls by","fell by","sell less","sells less","drop","go down","goes down"],"sample":"summer sales fall by about 20%"},{"t":{"en":"One idea","tr":"Tek bir fikir","fa":"یک ایده"},"find":["we could","i recommend","recommendation","i suggest","how about","why don't we"],"sample":"test a cold brew coffee in one café for a month"},{"t":{"en":"A reason with a number","tr":"Sayı içeren bir neden","fa":"یک دلیل با عدد"},"find":["why:","because","the reason","sold","grew","rose","per cent","percent"],"sample":"cold drinks sold 30% more this year"},{"t":{"en":"A risk","tr":"Bir risk","fa":"یک ریسک"},"find":["risk","may not","might not","could fail","danger"],"sample":"may not sell on cool days, so test in one café first"},{"t":{"en":"The next step","tr":"Sonraki adım","fa":"قدم بعدی"},"find":["next step","if it sells","if it works","then we","after the test"],"sample":"if it sells 40 cups a day, all 12 cafés in June"}]},"exit":{"id":"c-int-11-x","course":"interview","unit":"int-11","type":"exit","items":[{"from":"int-11","kind":"mcq","prompt":"One person on a panel asks you a question. Where do you look?","options":["At the asker first, then the others too","Only at the most senior person there","Down at your notes, to stay on track"],"correct":0,"point":1,"why":{"en":"At the asker first, then the others too: everyone on the panel decides. Looking only at the senior person, or at your notes, leaves people out.","tr":"Önce soruyu sorana, sonra diğerlerine de: heyetteki herkes karar verir. Yalnızca kıdemli kişiye ya da notlarına bakmak diğerlerini dışarıda bırakır.","fa":"اول به کسی که پرسید و بعد به بقیه هم نگاه کن، چون همه‌ی اعضای هیئت تصمیم می‌گیرند. نگاه کردن فقط به نفر ارشد یا به یادداشت‌ها بقیه را کنار می‌گذارد."},"hint2":{"en":"Everyone on the panel decides, but one person asked. How do you answer that person without leaving the others out?","tr":"Heyetteki herkes karar verir, ama soruyu bir kişi sordu. Diğerlerini dışarıda bırakmadan o kişiye nasıl cevap verirsin?","fa":"همه‌ی اعضای هیئت تصمیم می‌گیرند، ولی سؤال را یک نفر پرسیده. چطور به همان نفر جواب می‌دهی بدون اینکه بقیه را کنار بگذاری؟"}},{"from":"int-11","kind":"blank","prompt":"How about ___ the idea in one café first?","options":["testing","test","to test"],"correct":0,"point":2,"why":{"en":"testing: after 'How about', use -ing. 'Test' and 'to test' don't follow How about.","tr":"testing: 'How about'tan sonra -ing gelir. 'Test' ve 'to test' How about'tan sonra gelmez.","fa":"testing درست است، چون بعد از How about فعل ing‌دار می‌آید. test و to test بعد از How about نمی‌آیند."}},{"from":"int-11","kind":"mcq","prompt":"You miss the end of a long question. What is best?","options":["Say which part you missed, and ask","Guess what they meant, and start","Nod, then give a general answer"],"correct":0,"point":1,"why":{"en":"Say which part you missed, and ask: they repeat only that part, and your answer fits the real question. Guessing or a general answer may miss the point.","tr":"Hangi kısmı kaçırdığını söyle ve sor: yalnızca o kısmı tekrar ederler, cevabın da asıl soruya uyar. Tahmin ya da genel bir cevap konuyu kaçırabilir.","fa":"بگو کدام قسمت را نشنیدی و بپرس؛ فقط همان قسمت را تکرار می‌کنند و جوابت به سؤال واقعی می‌خورد. حدس زدن یا جواب کلی ممکن است به اصل سؤال نخورد."},"hint2":{"en":"A guessed answer may miss the point. What can you do instead, in one short sentence?","tr":"Tahmine dayalı bir cevap asıl noktayı kaçırabilir. Bunun yerine tek kısa bir cümleyle ne yapabilirsin?","fa":"جوابی که بر اساس حدس باشد ممکن است اصل مطلب را نگیرد. به‌جایش با یک جمله‌ی کوتاه چه می‌توانی بکنی؟"}},{"from":"int-6","kind":"blank","prompt":"Hold on, my headphones ___ properly at the moment.","options":["aren't working","don't work","not working"],"correct":0,"point":2,"why":{"en":"aren't working: 'at the moment' is a problem now, so use are not + -ing. 'Don't work' sounds like they never work, and 'not working' has no verb.","tr":"aren't working: 'at the moment' şu anki bir sorundur, bu yüzden are not + -ing. 'Don't work' hiç çalışmıyorlarmış gibi duyulur; 'not working'te fiil yoktur.","fa":"aren't working درست است، چون at the moment یعنی مشکل الان هست و are not و فعل ing‌دار لازم است. don't work یعنی هیچ‌وقت کار نمی‌کنند و not working فعل ندارد."}},{"from":"int-5","kind":"blank","prompt":"I ___ to a customer when the system went down.","options":["was talking","talked","have talked"],"correct":0,"point":2,"why":{"en":"was talking: the background action takes the past continuous, and the system going down cuts into it. 'Talked' loses the background; 'have talked' links to now.","tr":"was talking: arka plan eylemi past continuous alır ve sistemin çökmesi onu böler. 'Talked' arka planı kaybeder; 'have talked' şimdiye bağlar.","fa":"was talking درست است، چون کار پس‌زمینه گذشته‌ی استمراری می‌خواهد و از کار افتادن سیستم وسطش رخ می‌دهد. talked پس‌زمینه را از بین می‌برد و have talked به الان ربط دارد."}},{"from":"int-1","kind":"mcq","prompt":"Your introduction ends with \"why\". What should it say?","options":["Why you want this job","Why you left your old job","Why you chose your degree"],"correct":0,"point":1,"why":{"en":"Why you want this job: it links your story to them. Leaving your old job sounds negative, and your degree belongs earlier, if at all.","tr":"Bu işi neden istediğin: hikâyeni onlara bağlar. Eski işten ayrılmak olumsuz duyulur; okuduğun alanı neden seçtiğin ise gerekirse daha önce gelir.","fa":"چرا این کار را می‌خواهی؛ داستانت را به آن‌ها وصل می‌کند. ترک کار قبلی منفی به نظر می‌رسد و رشته‌ی دانشگاهی، اگر لازم باشد، زودتر می‌آید."},"hint2":{"en":"The end of your introduction looks forward, to this job, not back to the past. Which answer does that?","tr":"Tanıtımının sonu geçmişe değil, ileriye, bu işe bakar. Hangi cevap bunu yapıyor?","fa":"پایان معرفی‌ات رو به جلو و به همین کار نگاه می‌کند، نه به گذشته. کدام جواب این کار را می‌کند؟"}}]},"explain":{"id":"c-int-11-e","course":"interview","unit":"int-11","type":"explain","level":"B1","title":{"en":"Panels, group tasks and tests","tr":"Heyetler, grup görevleri ve testler","fa":"هیئت مصاحبه، کار گروهی و آزمون"},"objective":{"en":"After this lesson, you can answer a panel, work well in a group task and a timed case task, and check a question you didn't catch.","tr":"Bu dersin sonunda bir heyete cevap verebilecek, grup görevinde ve süreli bir vaka görevinde iyi çalışabilecek ve kaçırdığın bir soruyu netleştirebileceksin.","fa":"بعد از این درس می‌توانی به هیئت مصاحبه جواب بدهی، در کار گروهی و کار موردی زمان‌دار خوب عمل کنی و سؤالی را که نشنیدی روشن کنی."},"hook":{"en":"Some interviews have a panel (three people asking), a group task with other candidates, or a short timed case task (a work problem to solve). The assessors, the people who score you, test the same things: do you include people, stay clear and finish on time? So use names, build on others and check the task first.","tr":"Bazı mülakatlarda bir heyet (soru soran üç kişi), diğer adaylarla bir grup görevi ya da kısa ve süreli bir vaka görevi (çözülecek bir iş sorunu) olur. Seni puanlayan değerlendiriciler hepsinde aynı şeylere bakar: İnsanları dahil ediyor musun, net kalıyor musun, zamanında bitiriyor musun? Bu yüzden isim kullan, başkalarının fikrine ekle ve önce görevi netleştir.","fa":"در بعضی مصاحبه‌ها هیئت مصاحبه داری (سه نفر که سؤال می‌پرسند)، یا با داوطلب‌های دیگر یک کار گروهی، یا یک کار موردی کوتاه و زمان‌دار (یک مسئله‌ی کاری که باید حلش کنی). ارزیاب‌ها، یعنی کسانی که به تو نمره می‌دهند، در همه‌ی این‌ها یک چیز را می‌سنجند: دیگران را درگیر می‌کنی، روشن حرف می‌زنی و کار را سر وقت تمام می‌کنی؟ پس اسم‌ها را به کار ببر، حرف دیگران را ادامه بده و اول کار را روشن کن."},"before":{"en":"Suggest one idea for a work problem, with one reason, in two sentences.","tr":"Bir iş sorunu için iki cümleyle, bir nedeniyle birlikte tek bir fikir öner.","fa":"برای یک مشکل کاری، در دو جمله یک ایده پیشنهاد بده، همراه با یک دلیل."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Include everyone, build, check the task","tr":"Herkesi dahil et, üzerine ekle, görevi netleştir","fa":"همه را درگیر کن، حرف دیگران را ادامه بده، کار را روشن کن"},"steps":[{"en":"Panel: answer the person who asked, then look at the others too, because they all decide.","tr":"Heyet: soruyu sorana cevap ver, sonra diğerlerine de bak, çünkü kararı hepsi birlikte verir.","fa":"در هیئت مصاحبه به کسی که پرسید جواب بده و بعد به بقیه هم نگاه کن، چون تصمیم را همه با هم می‌گیرند.","ex":"That's a good question, Ms Lopez."},{"en":"Group task: speak early, build on others and bring quiet people in. Assessors watch how you treat people.","tr":"Grup görevi: erken konuş, başkalarının fikrine ekle ve sessiz kalanları dahil et. Değerlendiriciler insanlara nasıl davrandığına bakar.","fa":"در کار گروهی زود حرف بزن، حرف دیگران را ادامه بده و ساکت‌ها را هم وارد بحث کن. ارزیاب‌ها می‌بینند با دیگران چطور رفتار می‌کنی.","ex":"Sara, what do you think?"},{"en":"Case task: read the brief twice and check what is unclear, so you solve the right problem.","tr":"Vaka görevi: talimatı iki kez oku ve belirsiz olanı sor; böylece doğru sorunu çözersin.","fa":"در کار موردی دستورالعمل را دو بار بخوان و هر چیز نامشخصی را بپرس تا مسئله‌ی درست را حل کنی.","ex":"Just to check: one idea or three?"},{"en":"Missed part of a question? Say which part, because a guessed answer may miss the point.","tr":"Sorunun bir kısmını mı kaçırdın? Hangi kısım olduğunu söyle, çünkü tahminle verilen cevap konuyu kaçırabilir.","fa":"بخشی از سؤال را نشنیدی؟ بگو کدام بخش، چون جوابی که با حدس بدهی ممکن است به اصل سؤال نخورد.","ex":"Sorry, I missed the last part."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Suggestions in a group: could, Why don't we, How about + -ing","tr":"Grupta öneri: could, Why don't we, How about + -ing","fa":"پیشنهاد دادن در گروه: could، Why don't we و How about + ‎-ing"},"steps":[{"en":"Use could + verb for a soft idea, because it leaves room for others.","tr":"Yumuşak bir fikir için could + fiil kullan, çünkü başkalarına da yer bırakır.","fa":"برای پیشنهاد نرم could و فعل ساده بیاور، چون برای نظر دیگران هم جا می‌گذارد.","ex":"We could start with the budget."},{"en":"Ask with Why don't we + verb? to invite the whole group.","tr":"Bütün grubu davet etmek için Why don't we + fiil? diye sor.","fa":"برای اینکه همه‌ی گروه را به بحث دعوت کنی، با Why don't we و فعل ساده بپرس.","ex":"Why don't we hear from everyone first?"},{"en":"After How about, use -ing, because about is a preposition.","tr":"How about'tan sonra -ing kullan, çünkü about bir edattır.","fa":"بعد از How about فعل ing‌دار بیاور، چون about حرف اضافه است و بعد از حرف اضافه فعل ing می‌گیرد.","ex":"How about testing it in one shop?"}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Soft suggestion: could + verb","We could start with the budget."],["Ask the group: Why don't we + verb?","Why don't we hear from everyone first?"],["How about + -ing?","How about testing it in one shop?"],["Build first: Building on ...","Building on Jon's idea, we could ask the client."]]},"tip":{"en":"Turkish and Persian keep statement order in questions, so learners say 'Why we don't vote?'. English puts don't before we.","tr":"Türkçede soru da düz cümle sırasıyla kurulur; bu yüzden 'Why we don't vote?' denir. İngilizcede don't, we'den önce gelir: Why don't we vote?","fa":"در فارسی جمله‌ی پرسشی همان ترتیب جمله‌ی خبری را دارد؛ برای همین می‌گوییم «Why we don't vote?». در انگلیسی don't قبل از we می‌آید: Why don't we vote?"},"wrong":"Why we don't hear from everyone first?","right":"Why don't we hear from everyone first?"},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"In the room","tr":"Odada","fa":"در اتاق مصاحبه"},"body":{"en":"Sit up, face the panel and keep your hands still. Handshakes differ: some people do not shake hands, so follow their lead. In a group task, nod while others speak and never talk over them. Assessors also notice how you treat the receptionist.","tr":"Dik otur, heyete dön ve ellerini sakin tut. Tokalaşma kişiden kişiye değişir: bazı insanlar el sıkışmaz, bu yüzden karşındakini takip et. Grup görevinde başkaları konuşurken başını salla ve sözlerini kesme. Değerlendiriciler resepsiyondaki kişiye nasıl davrandığını da fark eder.","fa":"صاف بنشین، رو به هیئت باش و دست‌هایت را آرام نگه دار. دست دادن در هر جا فرق دارد: بعضی‌ها دست نمی‌دهند، پس ببین طرف مقابل چه می‌کند. در کار گروهی وقتی دیگران حرف می‌زنند سر تکان بده و وسط حرفشان نپر. ارزیاب‌ها به رفتارت با مسئول پذیرش هم توجه می‌کنند."},"phrases":[{"phrase":"That's a good question, Ms Lopez.","meaning":{"en":"Uses the name of the person who asked.","tr":"Soruyu soranın adını kullanır.","fa":"اسم کسی را که پرسیده به کار می‌برد."}},{"phrase":"Sorry, I missed the last part.","meaning":{"en":"Says exactly what you didn't catch.","tr":"Tam olarak neyi kaçırdığını söyler.","fa":"دقیقاً می‌گوید کدام قسمت را نشنیدی."}},{"phrase":"Building on Jon's idea, ...","meaning":{"en":"Adds to someone else's idea before yours.","tr":"Kendi fikrinden önce başkasının fikrine ekler.","fa":"پیش از ایده‌ی خودت، ایده‌ی کس دیگری را ادامه می‌دهد."}},{"phrase":"brief","meaning":{"en":"Here: the written instructions for a task.","tr":"burada: bir görevin yazılı talimatları.","fa":"اینجا: دستورالعمل نوشته‌شده‌ی یک کار."}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From a guess to a clear check","tr":"Tahminden net bir kontrole","fa":"از حدس زدن به پرسیدن روشن"},"item":"Weak: Yes, okay. So, teamwork is very important, and I am a team player. Your facts: the question was long and fast; you missed the last part; you think it was about a time your team disagreed.","answer":"Sorry, I missed the last part. Did you ask about a time my team disagreed?","walk":[{"en":"Say sorry once, and name the part you missed.","tr":"Bir kez özür dile ve kaçırdığın kısmı söyle.","fa":"یک بار عذرخواهی کن و بگو کدام قسمت را نشنیدی."},{"en":"Check your guess as a yes-or-no question.","tr":"Tahminini evet-hayır sorusuyla kontrol et.","fa":"حدست را با یک سؤال بله‌یا‌نه بپرس."},{"en":"Then answer the real question with a true story.","tr":"Sonra asıl soruyu gerçek bir hikâyeyle cevapla.","fa":"بعد با یک ماجرای واقعی به سؤال اصلی جواب بده."}],"cut":["Yes, okay","teamwork is very important","I am a team player"],"cutHint":{"en":"Tap what pretends you heard the whole question.","tr":"Sorunun tamamını duymuş gibi yapan kısımlara dokun.","fa":"روی چیزهایی بزن که وانمود می‌کنند کل سؤال را شنیده‌ای."}},"quick":{"prompt":"In a case task, before you start, ___.","options":["read the brief twice and check anything unclear","start writing at once to save time","ask the other candidates what they will write"],"correct":0,"why":{"en":"read the brief twice and check anything unclear: then you solve the right problem.","tr":"read the brief twice and check anything unclear: böylece doğru sorunu çözersin.","fa":"جواب ⁨read the brief twice and check anything unclear⁩ است، چون این‌طوری همان مسئله‌ای را حل می‌کنی که از تو خواسته‌اند."}},"remember":{"en":"Names, build, check. You can now answer a panel, work well in a group task and a timed case task, and check a question you didn't catch. Next, you judge group-task lines, practise a panel and write a case recommendation.","tr":"İsim kullan, üzerine ekle, netleştir. Artık bir heyete cevap verebilir, grup görevinde ve süreli bir vaka görevinde iyi çalışabilir ve kaçırdığın bir soruyu netleştirebilirsin. Sırada grup görevi cümlelerini değerlendirmek, bir heyet alıştırması ve bir vaka önerisi yazmak var.","fa":"اسم‌ها را بگو، حرف دیگران را ادامه بده و کار را روشن کن. حالا می‌توانی به هیئت مصاحبه جواب بدهی، در کار گروهی و کار موردی زمان‌دار خوب عمل کنی و سؤالی را که نشنیدی روشن کنی. در ادامه جمله‌های کار گروهی را ارزیابی می‌کنی، با یک هیئت مصاحبه تمرین می‌کنی و یک پیشنهاد برای کار موردی می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Disagree softly and sum up","tr":"Kibarca karşı çık ve özetle","fa":"مخالفت نرم و جمع‌بندی"},"steps":[{"en":"Disagree with a question: Wouldn't it be better to + verb?","tr":"Soruyla karşı çık: Wouldn't it be better to + fiil?","fa":"مخالفتت را با سؤال بگو: Wouldn't it be better to و فعل.","ex":"Wouldn't it be better to test it first?"},{"en":"Accept the point, then give your reason with but.","tr":"Önce görüşü kabul et, sonra but ile nedenini söyle.","fa":"اول حرف طرف را بپذیر و بعد با but دلیلت را بگو.","ex":"I see your point, but the budget is small."},{"en":"Close the task: So, to sum up, + what you agreed.","tr":"Görevi kapat: So, to sum up, + üzerinde anlaştığınız şey.","fa":"کار را جمع کن: So, to sum up و بعد چیزی که رویش توافق کردید.","ex":"So, to sum up, we start in one café."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Wouldn't it be better to + verb?","Wouldn't it be better to test it first?"],["I see your point, but + reason","I see your point, but the budget is small."],["So, to sum up, + what you agreed","So, to sum up, we start in one café."]]},"body":{"en":"B2: in your speaking, disagree once with 'I see your point, but...' and close with 'So, to sum up, ...'.","tr":"B2: konuşmanda bir kez 'I see your point, but...' ile karşı çık ve 'So, to sum up, ...' ile kapat.","fa":"در مسیر B2: در صحبتت یک بار با «I see your point, but...» مخالفت کن و با «So, to sum up, ...» جمع‌بندی کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
